from itertools import combinations


def _route(data, coupon_rule, minimum_duration):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    initial_mask = bit.get(source, 0)
    start_key = (source, initial_mask, 0)
    distances = {start_key: data["start"]}
    queue = [(data["start"], source, initial_mask, 0)]
    while queue:
        time, node, mask, used = heapq.heappop(queue)
        key = (node, mask, used)
        if distances.get(key) != time:
            continue
        if (node == data["target"] and mask == full and
                (coupon_rule == "at_most" or used == data["coupons"])):
            return {"arrival": time}
        for edge in data["edges"]:
            if edge["u"] != node:
                continue
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < data["coupons"]:
                duration = max(minimum_duration,
                               edge["duration"] - edge.get("discount", 0))
                options.append((duration, used + 1))
            for duration, next_used in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_key = (next_node, next_mask, next_used)
                if arrival < distances.get(next_key, float("inf")):
                    distances[next_key] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_used))
    return {"arrival": None}


def _build_route(coupon_rule, minimum_duration):
    return lambda data: _route(data, coupon_rule, minimum_duration)


def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (event.get("revision", 0), position)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, data["rounding"])
            tax = rounded(net * event.get("tax_bp", 0), 10000, data["rounding"])
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        best_vector = None
        best = None

        def cyclic(assigned):
            visiting, done = set(), set()

            def visit(name):
                if name in visiting:
                    return True
                if name in done:
                    return False
                visiting.add(name)
                row = assigned[name]
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    if visit(dep["name"]):
                        return True
                visiting.remove(name)
                done.add(name)
                return False

            return any(visit(name) for name in assigned if name not in done)

        def search(assigned, requirements):
            nonlocal best_vector, best
            for name, row in assigned.items():
                if any(not low <= row["version"] <= high
                       for low, high in requirements.get(name, [])):
                    return
            pending = [name for name in requirements if name not in assigned]
            if not pending:
                if cyclic(assigned):
                    return
                vector = tuple(assigned[name]["version"] if name in assigned else -1
                               for name in names)
                if best_vector is None or vector < best_vector:
                    best_vector = vector
                    best = {name: assigned[name]["version"] for name in assigned}
                return

            name = min(pending)
            constraints = requirements[name]
            rows = [row for row in packages[name]
                    if all(low <= row["version"] <= high for low, high in constraints)
                    and row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
            for row in sorted(rows, key=lambda item: item["version"]):
                next_assigned = dict(assigned)
                next_assigned[name] = row
                next_requirements = {key: list(value) for key, value in requirements.items()}
                valid = True
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    dep_name = dep["name"]
                    next_requirements.setdefault(dep_name, []).append((dep["min"], dep["max"]))
                    if dep_name in next_assigned and not dep["min"] <= next_assigned[dep_name]["version"] <= dep["max"]:
                        valid = False
                        break
                if valid:
                    search(next_assigned, next_requirements)

        requirements = {name: [(bounds[0], bounds[1])]
                        for name, bounds in data["roots"].items()}
        search({}, requirements)
        return {"versions": best} if best is not None else {"error": "unsatisfiable"}
    return solve


def _build_component_08():
    def solve(data):
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        options = [job for job in data["jobs"] if job["id"] not in blocked]
        quotas = data.get("quotas", {})
        best_ids = None
        best_value = None
        for subset in combinations(options, k):
            ids = tuple(sorted(job["id"] for job in subset))
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            intervals = sorted((job["start"], job["end"]) for job in subset)
            if any(intervals[i - 1][1] > intervals[i][0]
                   for i in range(1, len(intervals))):
                continue
            value = sum(job["value"] for job in subset)
            if (best_value is None or value > best_value or
                    (value == best_value and ids > best_ids)):
                best_value, best_ids = value, ids
        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


